import {CODES,YEARS,DATA_VERSION,ENGINE_VERSION,DEFAULT_MIX,defaultState,calculate,balanceMix,modifierFor} from './engine.mjs?v=2026-11-05.10';
import {defaultView,validYears,monthlySeries,significantEvents,serialize,restore,monthlyCSV,descendingYears,comparisonYears} from './monthly.mjs?v=2026-11-05.10';
import {policyFor} from './policies.mjs?v=2026-11-05.10';
import {drawMonthly} from './charts.mjs?v=2026-11-05.10';
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LABELS=['Established · level 2','Established · level 3','Established · level 4','Established · level 5','New patient · level 2','New patient · level 3','New patient · level 4','New patient · level 5'];
let data,state=defaultState(),view=defaultView(),result,points,events,valid=false,blocked=false,shared=false,lastState,resizeTimer,liveTimer,dialogReturn;
$('mix-inputs').innerHTML=CODES.map((c,i)=>(i===0?'<h3 class="mix-group">Established patients</h3>':i===4?'<h3 class="mix-group">New patients</h3>':'')+`<div class="mix-row"><label for="mix-${c}"><b>${c}</b><small>${LABELS[i]}</small></label><div class="percent-input"><input id="mix-${c}" type="number" min="0" max="100" step="0.01" inputmode="decimal" value="${DEFAULT_MIX[c]}"><span aria-hidden="true">%</span></div></div>`).join('');
function sourceLink(id,page,label){const s=data.sources.find(s=>s.id===id);return s?.url?`<a href="${esc(s.url)}${page?'#page='+page:''}" target="_blank" rel="noopener">${esc(label||s.title||id)} ↗</a>`:esc(id);}
function expose(){window.PAYMENT_EXPLORER={data,state:structuredClone(state),view:structuredClone(view),result:valid?result:{valid:false},points,engineVersion:ENGINE_VERSION};}
function announce(text){clearTimeout(liveTimer);liveTimer=setTimeout(()=>$('status').textContent=text,350);}
function sync(){for(const e of document.querySelectorAll('[name=profile]'))e.checked=e.value===state.profile;for(const k of ['visits','days','complexity'])$(k).value=state[k];$('complexity-number').value=state.complexity;for(const c of CODES)$('mix-'+c).value=state.mix[c];}
function read(){for(const k of ['visits','days'])state[k]=$(k).value===''?NaN:Number($(k).value);for(const c of CODES)state.mix[c]=$('mix-'+c).value===''?NaN:Number($('mix-'+c).value);}
function updateURL(){if(valid&&shared&&!blocked)history.replaceState(null,'','#scenario='+serialize(lastState,view));}
function render(){const next=calculate(data,state);valid=next.valid&&validYears(view);$('error').hidden=valid;$('error').textContent=next.errors?.join(' ')||(!validYears(view)?'Choose two to four different years.':'');$('stale-note').hidden=valid;for(const id of ['share','export'])$(id).disabled=!valid||blocked;for(const el of document.querySelectorAll('.comparison-table select,.comparison-table button'))el.disabled=!valid||blocked;for(const id of ['history-panel','comparison-table'])$(id).classList.toggle('is-stale',!valid);for(const e of document.querySelectorAll('.event-button'))e.disabled=!valid;const sum=CODES.reduce((a,c)=>a+(Number.isFinite(state.mix[c])?state.mix[c]:0),0);$('mix-total').textContent='Total: '+Number(sum.toFixed(2))+'%';$('mix-total').classList.toggle('invalid',Math.abs(sum-100)>.005);$('practice-summary').textContent=`${state.profile==='qp'?'QP + B2':'Non-QP + B1'} · ${Number.isFinite(state.visits*state.days)?(state.visits*state.days).toLocaleString('en-US',{maximumFractionDigits:1}):'—'} visits/month · ${Number.isFinite(state.complexity)?state.complexity:'—'}% complexity`;$('complexity-note').textContent=`Model: established visits only. G2211 2024–26; ${modifierFor(state)} 2027.`;if(!valid){expose();return;}result=next;lastState=structuredClone(state);points=monthlySeries(result);events=significantEvents(data,state);$('volume-summary').textContent=`Same ${(state.visits*state.days).toLocaleString('en-US',{maximumFractionDigits:1})} visits/month and mix every year.`;renderChart();renderTable();updateURL();expose();window.PAYMENT_READY=true;announce('Monthly payments updated for your practice.');}
function renderChart(){drawMonthly($('history-chart'),$('event-buttons'),{points,events,onOpen:openYear});}
function renderTable(){
 view.years=comparisonYears(view.years);
 const labels={nominal:['Nominal','That year’s dollars'],CPI:['CPI-adjusted','2027 dollars*'],MEI:['MEI-adjusted','2027 dollars*'],cf:['CF','$/RVU · year’s dollars']};
 const amount=(p,key)=>key==='cf'?'$'+p.cf.toFixed(4):money(p[key]);
 const yearControl=(year,i,mobile=false)=>`<label class="year-control-label sr-only" for="compare-year-${mobile?'mobile-':''}${i}">Comparison year ${i+1}</label><select id="compare-year-${mobile?'mobile-':''}${i}" data-year-index="${i}" aria-label="Comparison year ${i+1}">${[...YEARS].reverse().map(y=>`<option value="${y}"${year===y?' selected':''}${view.years.includes(y)&&year!==y?' disabled':''}>${y}</option>`).join('')}</select>`;
 $('comparison-table').innerHTML=`<div class="desktop-year-table"><table><caption class="sr-only">Monthly payments for ${view.years.join(', ')}, newest first. Adjusted amounts use 2027 dollars.</caption><thead><tr><th scope="col">Measure</th>${view.years.map((year,i)=>`<th scope="col">${yearControl(year,i)}</th>`).join('')}</tr></thead><tbody>${Object.entries(labels).map(([key,[title,unit]])=>`<tr class="${key}"><th scope="row">${title}<small>${unit}</small></th>${view.years.map(year=>`<td>${amount(points.find(p=>p.year===year),key)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="mobile-year-cards">${view.years.map((year,i)=>{const p=points.find(p=>p.year===year);return `<section class="year-card" aria-label="${year} monthly comparison"><div class="year-card-heading">${yearControl(year,i,true)}</div><dl>${Object.entries(labels).map(([key,[title,unit]])=>`<div class="${key}"><dt>${title}<small>${unit}</small></dt><dd>${amount(p,key)}</dd></div>`).join('')}</dl></section>`;}).join('')}</div>`;
 const refresh=focusYear=>{renderTable();updateURL();expose();if(focusYear){const mobile=matchMedia('(max-width:760px)').matches;[...document.querySelectorAll(mobile?'.mobile-year-cards select':'.desktop-year-table select')].find(e=>+e.value===focusYear)?.focus({preventScroll:true});}announce('Comparison updated, newest year first.');};
 for(const select of $('comparison-table').querySelectorAll('[data-year-index]'))select.onchange=()=>{const year=+select.value;view.years[+select.dataset.yearIndex]=year;refresh(year);};
 for(const control of $('comparison-table').querySelectorAll('select,button'))control.disabled=!valid||blocked;

}
function openYear(year,origin){
 if(!valid)return;const policy=policyFor(data,lastState,year);if(!policy)return;dialogReturn=origin;
 $('event-title').textContent=`${year} · ${policy.title}`;
 $('event-content').innerHTML=`<ul class="policy-changes">${policy.bullets.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>${policy.examples.length?`<div class="policy-rvus"><h3>${esc(policy.componentLabel)}</h3><table><caption>${year-1} → ${year} · examples from your selected visit mix</caption><thead><tr><th scope="col">Code</th><th scope="col">${year-1}</th><th scope="col">${year}</th></tr></thead><tbody>${policy.examples.map(r=>`<tr><th scope="row">${r.code}</th><td>${r.before.toFixed(2)}</td><td>${r.after.toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="policy-source"><a href="${esc(policy.url)}" target="_blank" rel="noopener">Policy source ↗</a>${policy.examples.length?' · '+sourceLink(policy.examples[0].sourceId,policy.examples[0].sourcePage,'RVU source'):''}</p>`;
 document.body.classList.add('modal-open');$('event-dialog').showModal();
}
$('close-event').onclick=()=>$('event-dialog').close();$('event-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');return (dialogReturn?.isConnected?dialogReturn:document.querySelector(`.event-button[data-year="${dialogReturn?.dataset.year}"]`)||$('history-title')).focus({preventScroll:true});});$('event-dialog').onclick=e=>{if(e.target===$('event-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
function changed(){read();$('share-status').textContent='';$('export-status').textContent='';$('share-fallback').hidden=true;render();}
for(const e of document.querySelectorAll('[name=profile]'))e.onchange=()=>{state.profile=e.value;changed();};for(const id of ['visits','days',...CODES.map(c=>'mix-'+c)])$(id).oninput=()=>{if(id.startsWith('mix-'))$('mix-preset').value='custom';changed();};for(const id of ['complexity','complexity-number'])$(id).oninput=()=>{state.complexity=$(id).value===''?NaN:Number($(id).value);if(Number.isFinite(state.complexity))$(id==='complexity'?'complexity-number':'complexity').value=state.complexity;changed();};
$('balance').onclick=()=>{read();state.mix=balanceMix(state.mix);for(const c of CODES)$('mix-'+c).value=state.mix[c];changed();};$('mix-preset').onchange=e=>{if(e.target.value==='custom')return;state.mix=e.target.value==='simple'?Object.fromEntries(CODES.map(c=>[c,c==='99214'?70:c==='99213'?30:0])):{...DEFAULT_MIX};for(const c of CODES)$('mix-'+c).value=state.mix[c];changed();};
function reset(){state=defaultState();view=defaultView();shared=false;blocked=false;$('scenario-warning').hidden=true;$('mix-preset').value='documented';history.replaceState(null,'',location.pathname+location.search);sync();render();}$('reset').onclick=reset;$('accept-current').onclick=reset;
$('settings-toggle').onclick=()=>{const open=document.querySelector('.settings').classList.toggle('settings-open');$('settings-toggle').setAttribute('aria-expanded',String(open));$('settings-toggle').textContent=open?'Close':'Adjust';};$('settings-done').onclick=()=>{if(!valid){$('error').scrollIntoView({block:'center'});return;}document.querySelector('.settings').classList.remove('settings-open');$('settings-toggle').setAttribute('aria-expanded','false');$('settings-toggle').textContent='Adjust';$('history-title').setAttribute('tabindex','-1');$('history-title').focus();};
$('share').onclick=async()=>{if(!valid||blocked)return;shared=true;updateURL();try{await navigator.clipboard.writeText(location.href);$('share-status').textContent='Copied with your settings and years';}catch{$('share-fallback').hidden=false;$('share-url').value=location.href;$('share-url').select();$('share-status').textContent='Select and copy the link below';}};
$('export').onclick=()=>{if(!valid||blocked)return;const url=URL.createObjectURL(new Blob([monthlyCSV(data,lastState,result,view)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='medicare-monthly-1992-2027.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('export-status').textContent='Monthly data downloaded';};
function apply(){state=defaultState();view=defaultView();blocked=false;shared=false;if(location.hash.startsWith('#scenario=')){const r=restore(location.hash.slice(10));if(r.state){state=r.state;view=r.view;shared=true;}else{blocked=true;$('scenario-message').textContent=r.error;}}$('scenario-warning').hidden=!blocked;sync();render();}
window.addEventListener('hashchange',()=>{if(data&&location.hash.startsWith('#scenario='))apply();});window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(points)renderChart();},100);});document.addEventListener('click',e=>{const a=e.target.closest?.('a[href^="#"]');if(!a)return;const target=$(a.getAttribute('href').slice(1));if(!target)return;e.preventDefault();if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({block:'start'});const focus=target.querySelector('summary')||target;focus.focus({preventScroll:true});});
function methods(){$('methods-content').innerHTML=`<h3>Payment model</h3><p>These are modeled national Medicare office E/M allowed amounts, including patient share. They exclude geographic adjustments, practice expenses, collections, MIPS, sequestration and separate APM incentives. AWVs, TCM and procedures are outside this visit basket. The same code may represent different documentation or clinical work across years.</p><p>The model holds visits, working days, visit mix and complexity uptake constant. Each year uses its applicable RVUs and conversion factor. Claim lines are rounded to cents before calendar-day weighting across effective pricing periods.</p><p>The documented default mix is 342 established and 18 new-patient visits per month, scaled to your selected volume.</p><h3>2027: full-visit calculation</h3><p>The 2027 complexity uplift is applied to the full E/M fee, following the final-rule text. Non-QP uses B1; the QP + eligible ACO preset uses B2. </p><p>QP status alone does not establish B2 eligibility; the preset assumes eligible ACO participation. Non-QPs may also participate in eligible ACOs. Complexity billing is illustrative and applies to established visits in this model.</p><h3>Inflation and conversion factor</h3><p>Adjusted monthly payment = that year's nominal monthly payment × the 2027 index ÷ that year's index.  CF is the year’s dollars per RVU, not the payment for a complete visit.</p><p>CPI uses BLS annual averages through 2025. The MEI series uses CMS’s published annual update chain, including productivity adjustments, rather than realized practice-expense inflation. 2027 fees are scheduled future payments.</p><h3>Projected index assumptions</h3><p>The inflation adjustments use forecasts, not observed full-year inflation, for 2026 and 2027. CPI growth assumptions are 2.924% for 2026 and 2.547% for 2027, from CBO’s February 2026 annual-average projection. The CMS MEI update assumptions are 2.7% and 2.6%, respectively, including productivity adjustments.</p><p><a href="https://www.cbo.gov/publication/62105" target="_blank" rel="noopener">CBO projection</a> · <a href="https://public-inspection.federalregister.gov/2026-22743.pdf" target="_blank" rel="noopener">CMS 2027 MEI assumption</a></p><p>Every adjusted amount is expressed in 2027 dollars. For 2027 itself, the adjustment factor is the 2027 index divided by itself: 1. That is why all three lines meet in 2027.</p><h3>Historical pricing</h3><p>1992–1995 are national fee-schedule references excluding locality-specific charge-transition blending. Transitional practice-expense values and separate work adjustments are applied where required. The 1997–1998 work product retains precision; 2007–2008 adjusted work is rounded to two decimals before adding practice-expense and malpractice values. Annual prices use all covered effective periods.</p><h3>Data and sharing</h3><p>Dataset ${esc(data.version)}, updated ${esc(data.asOf)}, uses the validated source data. A shared link preserves the practice inputs and four comparison years. Older links fill missing years with defaults. </p><p><a href="data/schedule-${esc(data.version)}.json">Download source data</a></p>`;}
(async()=>{try{const r=await fetch('./data/schedule-'+DATA_VERSION+'.json');if(!r.ok)throw Error('Schedule unavailable');data=await r.json();if(data.version!==DATA_VERSION)throw Error('Unexpected data version');methods();apply();}catch(e){$('error').hidden=false;$('error').textContent='Could not load payment data: '+e.message;for(const id of ['share','export'])$(id).disabled=true;}})();
